# -*- coding: utf-8 -*-
import sys,json,hashlib
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np,torch
from PIL import Image,ImageDraw,ImageFont
from gongbi_training.cunfa_supervision import partial_role_loss
ROOT=LAB/'cunfa_band_checked_20261112';OLD=LAB/'cunfa_roles_v2_20261112'
def read(p):return json.loads(Path(p).read_text('utf8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 ds=read(ROOT/'dataset_manifest.json');result=read(ROOT/'results.json');audit=read(ROOT/'reference_coordinate_audit.json');protocol=result['protocol'];assert sha(ROOT/'dataset_manifest.json')==protocol['reference_dataset_sha256'];assert sha(ROOT/'foreground_refiner.pt')==result['checkpoint_sha256'];assert sha(OLD/'flat_roles.pt')==protocol['teacher_sha256'];assert sha(Path(__file__).with_name('cunfa_band_checked_train_20261112.py'))==protocol['script_sha256'];font=lambda n:ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',n);col=np.array([[234,239,226],[192,128,40],[40,135,180]],'uint8');rows=[]
 for r in ds['records']:
  assert sha(r['path'])==r['sha256'];z=np.load(r['path']);row=next(q for q in result['records'] if q['id']==r['id']);assert row['semantic_conditional_max_error']<1e-5
  preds={}
  for arm in ['v2_frozen','frozen_role_refiner']:
   p=np.load(ROOT/'predictions'/(r['id']+'_'+arm+'.npz'))['prediction'];Image.fromarray(col[p]).save(ROOT/'predictions'/(r['id']+'_'+arm+'.png'));preds[arm]='predictions/'+r['id']+'_'+arm+'.png'
  board=Image.new('RGB',(1200,440),'#f4f1e8');d=ImageDraw.Draw(board)
  for j,(im,title) in enumerate([(Image.fromarray(z['image']),'原始输入'),(Image.open(ROOT/preds['v2_frozen']),'上一轮三分类 · 原始输出'),(Image.open(ROOT/preds['frozen_role_refiner']),'冻结角色、修正范围 · 原始输出')]):
   im.thumbnail((385,340));board.paste(im,(j*400+6,42));d.text((j*400+6,7),title,font=font(19),fill='#243e32')
  d.text((8,390),'橙=结构，蓝=皴笔；未用参考遮罩裁剪，仍不是完整笔触。',font=font(21),fill='#815238');board.save(ROOT/'predictions'/(r['id']+'_comparison.jpg'),quality=95)
  rows.append(dict(id=r['id'],split=r['split'],input='references/'+r['id']+'_input.png',target='references/'+r['id']+'_target.png',overlay='references/'+r['id']+'_overlay.png',predictions=preds,scores=row['scores'],band_counts=r['band_counts'],guides=[dict(id=g['id'],zoom='references/'+g['id']+'_zoom.jpg',endpoint_status=g['endpoint_status']) for g in r['guides']]))
 # Real pixels only: three segments in the diagnostic work, nearest-neighbour
 # magnification for side-by-side inspection. No synthetic reconstruction.
 h=next(r for r in ds['records'] if r['id']=='H_14');z=np.load(h['path']);board=Image.new('RGB',(1200,720),'#f4f1e8');d=ImageDraw.Draw(board)
 for i,g in enumerate(h['guides']):
  q=np.array(g['points']);box=(max(0,int(q[:,0].min())-10),max(0,int(q[:,1].min())-10),min(z['image'].shape[1],int(q[:,0].max())+11),min(z['image'].shape[0],int(q[:,1].max())+11))
  for j,(im,title) in enumerate([(Image.fromarray(z['image']),'原图局部'),(Image.open(ROOT/'predictions/H_14_v2_frozen.png'),'上一轮原始范围'),(Image.open(ROOT/'predictions/H_14_frozen_role_refiner.png'),'本轮原始范围')]):
   a=im.crop(box);a=a.resize((a.width*4,a.height*4),Image.Resampling.NEAREST);a.thumbnail((385,190));board.paste(a,(j*400+5,i*240+30));d.text((j*400+5,i*240+3),g['id']+' · '+title,font=font(17),fill='#243e32')
 board.save(ROOT/'width_comparison.jpg',quality=95)
 scores=result['diagnostic']['scores'];a=scores['v2_frozen']['band_ink'];b=scores['frozen_role_refiner']['band_ink'];decision=dict(adopted=False,valid_as_exploratory_interval_check_only=True,prior_misplaced_reference_runs_invalidated=True,near_paper_improved=b['near_paper_false_ink']<a['near_paper_false_ink'],ink_retention_not_decreased=b['ink_core_recall']>=a['ink_core_recall'],no_independent_expert_ink_mask=True,no_new_blind_test=True,no_complete_stroke_or_endpoint_gold=True,robot_connected=False)
 (ROOT/'decision.json').write_text(json.dumps(decision,ensure_ascii=False,indent=2),encoding='utf8');(ROOT/'report_data.json').write_text(json.dumps(dict(records=rows,diagnostic=result['diagnostic'],decision=decision,audit=audit),ensure_ascii=False,indent=2),encoding='utf8')
 # Test the actual corrected partial targets, including ignored edge bands.
 for r in ds['records']:
  t=np.load(r['path'])['band_targets'];x=torch.randn(1,3,*t.shape,requires_grad=True);loss=partial_role_loss(x,torch.from_numpy(t.astype('int64'))[None]);loss.backward();assert torch.count_nonzero(x.grad[0,:,t==255])==0
 policy=read(LAB/'cunfa_role_reference_20261112/legacy_policy_audit.json');assert sha(LAB/'cunfa_fresh_validation_20261111/test_manifest.json')==policy['legacy_manifest_sha256']
 checks=dict(reference_and_model_hashes_match=True,training_code_hash_matches_protocol=True,unknown_edge_gradient_zero=True,conditional_roles_preserved=True,max_conditional_error=max(r['semantic_conditional_max_error'] for r in result['records']),prior_bad_reference_metrics_invalidated=True,old_v2_model_unchanged=True,old_13_test_manifest_unchanged=True,corrected_reference_uses_image_evidence_not_model_output=True,exact_ink_mask_not_claimed=True,repeat_diagnostic_not_blind=True,model_adopted=False,robot_connected=False)
 (ROOT/'verification.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf8')
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>墨带范围与参考校验 · 离线复核</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#243e32;font:16px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1400px;margin:auto;padding:28px}h1{font-size:30px;line-height:1.35}h2{font-size:23px;margin-top:32px}.note{background:#fff9e8;border-left:5px solid #b57c3c;padding:16px}.warn{color:#914c32}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{background:#fffdf7;border:1px solid #d9d8c9;border-radius:8px;padding:12px}img{max-width:100%;height:auto;display:block;max-height:430px;margin:auto}select{font:inherit;padding:8px;max-width:100%;background:#fffdf7;border:1px solid #a4b3a4;border-radius:6px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #d7d9c9}.scroll{overflow:auto}.controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:14px 0}small{color:#66786a}a{color:#236b61}code{overflow-wrap:anywhere}@media(max-width:650px){main{padding:15px}.grid{grid-template-columns:1fr}h1{font-size:25px}td,th{font-size:13px;padding:6px}}</style><main><small>2026-11-12 · 离线研究 · 未连接机械臂</small><h1>先校验参考，再限制墨带扩张</h1><p class="note"><b id="conclusion"></b><br>本轮尚未得到完整墨带、交叉分笔或可靠收笔。仍不替换已认可绘画版本。</p>
<h2>1. 本轮发现并纠正的参考错误</h2><p class="warn">第一版手工边界参考中，几条曲线位置画偏，将纸面误标成墨迹。因此基于该版参考的两组整网续训和第一版范围修正试验已标记为不可用于验收，原始文件与指标原样保留。</p><p>剔除了两条不可靠训练参考和一条拥挤皴笔参考；校正清楚的墨迹路径，并在原生像素中做固定±2.5像素以内的图像依据辅助核查。仍有疑问的灰边、端点、遮挡和交叉处保持未知。纸面候选若含可见深色墨迹也予以排除。</p><p><b>这些是助手核查的保守区间参考，不是专家完整墨带真值。</b>图像依据辅助修正也意味着它不是独立于图像处理方法的金标准。原图分辨率与可确认信息没有因为放大而增加。</p>
<h2>2. 算法修改</h2><p>冻结上一轮三分类模型，保持“已是墨迹时属于结构还是皴笔”的条件概率，只训练一个小型卷积网络修正墨迹范围。输入为静态图和冻结模型的墨迹概率，不含参考曲线、前后帧或标签遮罩。原始输出没有按参考裁剪。</p><p>整网续训曾同时改变角色和范围，并出现退步；本轮分开检查这两个问题。当前阶段没有训练皴法名称、完整笔触实例、笔组顺序或真实毛笔参数。</p>
<h2>3. 同图查看参考与原始输出</h2><div class="controls"><label>观察 <select id="case"></select></label><span id="split"></span></div><div class="grid"><div class="card"><b>静态输入</b><img id="input"></div><div class="card"><b>墨迹 / 近邻纸面参考</b><img id="overlay"></div><div class="card"><b>灰色区域不参与监督</b><img id="target"></div></div><p>参考橙=结构、蓝=皴笔、绿=核查纸面；灰色未知。只有M_1与L_149_3新增了边界参考，另外两次训练观察用于重放旧参考。</p><div class="grid"><div class="card"><b>上一轮三分类原始输出</b><img id="old"></div><div class="card"><b>冻结角色、修正范围原始输出</b><img id="new"></div><div class="card"><b>范围检查</b><p>不能只看色块变小。需同时检查墨迹核心是否保留、淡线是否断裂，以及相邻笔迹是否仍粘连。</p><p>这依旧是角色概率图，不是中心线或可执行笔画。</p></div></div>
<h2>4. 只在同一复核局部的参考区间内比较</h2><div class="scroll"><table><thead><tr><th>方法</th><th>近邻纸面误报墨迹</th><th>确定墨迹保留</th><th>原有两类角色平均召回</th></tr></thead><tbody id="metrics"></tbody></table></div><p id="tradeoff"></p><p>近邻纸面与上一轮分散纸面核心是不同指标，不可把数值直接拼成改善趋势。本轮诊断仍复用了之前查看的H_14画面，原画家身份未核实，不是新作者盲测；也没有完整墨带IoU或真实笔宽准确率。</p>
<h2>5. 局部放大：看有没有靠删线“变细”</h2><img src="width_comparison.jpg"><p>放大使用原生像素局部。采样宽度只在有墨迹穿过参考中心的位置统计；没有穿过的点记作遗漏，不能把遗漏当作笔宽为零的改善。</p><div class="controls"><label>核查片段 <select id="guide"></select></label></div><img id="zoom"><p id="endpoint"></p>
<h2>6. 接下来仍需补的证据</h2><ol><li>增加可核实原作者、分辨率更高的完整局部墨带与相邻纸面；先确认真实细笔迹，再扩大监督。</li><li>交叉与干笔区域需要逐笔视频确认归属；当前不能强行续接或把每个断点都当提笔。</li><li>收笔需要清楚的最后着墨与提笔过程；当前只有少数可见墨迹尖端候选，不等于已验证机械臂起落点。</li></ol><p>本轮已有参考检查、冻结模型和原始预测可复核，但尚未完成整幅提取或实机绘画验收。</p><p><a href="protocol.json">冻结协议</a> · <a href="reference_coordinate_audit.json">参考错位检查与停用说明</a> · <a href="results.json">完整结果</a> · <a href="verification.json">程序检查</a></p></main>
<script>let D;const $=s=>document.getElementById(s),pct=x=>(x*100).toFixed(1)+'%';function guide(){let r=D.records[$('case').selectedIndex],g=r.guides[$('guide').selectedIndex];if(g){$('zoom').src=g.zoom;$('endpoint').textContent='端点状态：'+g.endpoint_status}else{$('zoom').removeAttribute('src');$('endpoint').textContent='此观察只重放旧参考，没有新增边界标记。'}}function show(){let r=D.records[$('case').selectedIndex];for(let n of ['input','overlay','target'])$(n).src=r[n];$('old').src=r.predictions.v2_frozen;$('new').src=r.predictions.frozen_role_refiner;$('split').textContent=r.split==='train'?'开发训练观察':'重复复核局部，非盲测';$('guide').replaceChildren();for(let g of r.guides){let o=document.createElement('option');o.textContent=g.id;$('guide').append(o)}guide()}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').selectedIndex=4;$('case').onchange=show;$('guide').onchange=guide;show();let s=d.diagnostic.scores;for(let [k,n] of [['v2_frozen','上一轮冻结模型'],['frozen_role_refiner','冻结角色、修正范围']]){let v=s[k],tr=document.createElement('tr');tr.innerHTML='<td>'+n+'</td><td>'+pct(v.band_ink.near_paper_false_ink)+'</td><td>'+pct(v.band_ink.ink_core_recall)+'</td><td>'+pct(v.core_roles.balanced_role_recall)+'</td>';$('metrics').append(tr)}let a=s.v2_frozen.band_ink,b=s.frozen_role_refiner.band_ink;$('conclusion').textContent=b.near_paper_false_ink<a.near_paper_false_ink&&b.ink_core_recall>=a.ink_core_recall?'修正参考后，这个复核局部减少了近邻纸面误检，同时保留了确定墨迹；样本和参考仍不足以通过整体验收。':'修正参考后，范围修正仍存在误检与漏线的取舍，尚未证明能在保留真实墨迹时稳定收窄。';$('tradeoff').textContent='本局部：近邻纸面误报 '+pct(a.near_paper_false_ink)+' → '+pct(b.near_paper_false_ink)+'；确定墨迹保留 '+pct(a.ink_core_recall)+' → '+pct(b.ink_core_recall)+'。';window.reportReady=true});</script></html>'''
 page=page.replace('样本和参考仍不足以通过整体验收。','但原有皴笔参考上仍有新增遗漏，样本和参考也不足以通过整体验收。')
 (ROOT/'index.html').write_text(page,encoding='utf8');print(json.dumps(dict(diagnostic=scores,checks=checks,decision=decision),ensure_ascii=False),flush=True)
if __name__=='__main__':main()
